/** @test */
public function hiding_a_feature_keeps_the_row_and_stops_it_printing_on_the_card()
{
    $plan = $this->positiveSsl();
    $this->assertGreaterThan(0, $plan->features()->count());

    $features = $plan->features()->orderBy('sort')->get()->map(function ($feature, $i) {
        // Hide the second row, keep the rest shown.
        return ['text' => $feature->feature] + ($i === 1 ? [] : ['shown' => '1']);
    })->all();

    $hiddenText = $plan->features()->orderBy('sort')->get()[1]->feature;

    $this->admin()
        ->post("/admin/ssl-plans/{$plan->id}", $this->payload($plan, $features))
        ->assertRedirect('/admin/ssl-plans');

