    // The customer page no longer prints it.
    $this->get('/services/ssl-certificate')
        ->assertOk()
        ->assertDontSee($hiddenText);

    // An unhidden sibling is still there.
    $this->get('/services/ssl-certificate')->assertSee('Domain Validation');
}

