/** @test */
public function deleting_a_feature_removes_it_from_the_database_and_the_card()
{
    $plan = $this->positiveSsl();
    $all = $plan->features()->orderBy('sort')->get();
    $doomed = $all->last();

    $this->get('/services/ssl-certificate')->assertSee($doomed->feature);

    // Deleting in the editor simply omits the row from the POST.
    $features = $all->take($all->count() - 1)->map(function ($feature) {
        return ['text' => $feature->feature, 'shown' => '1'];
    })->all();

    $this->admin()
        ->post("/admin/ssl-plans/{$plan->id}", $this->payload($plan, $features))
        ->assertRedirect('/admin/ssl-plans');

    $this->assertDatabaseMissing('ssl_plan_features', ['id' => $doomed->id]);
    $this->assertSame($all->count() - 1, $plan->fresh()->features()->count());

    $this->get('/services/ssl-certificate')->assertDontSee($doomed->feature);
}

